import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { ChevronDown, Globe } from 'lucide-react';
import { supportedLanguages } from '../i18n';

const LanguageSwitcher: React.FC = () => {
  const { i18n } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);

  const currentLanguage = i18n.language || 'en';
  const currentLangConfig = supportedLanguages[currentLanguage as keyof typeof supportedLanguages] || supportedLanguages.en;

  const changeLanguage = (languageCode: string) => {
    i18n.changeLanguage(languageCode);
    localStorage.setItem('selectedLanguage', languageCode);
    setIsOpen(false);
  };

  return (
    <div className="relative">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center space-x-2 px-3 py-2 rounded-lg text-gray-700 hover:text-calm-blue-600 hover:bg-gray-100 transition-colors duration-200"
        aria-label="Select language"
      >
        <Globe size={18} />
        <span className="text-sm font-medium hidden sm:inline">
          {currentLangConfig.nativeName}
        </span>
        <ChevronDown size={16} className={`transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      {isOpen && (
        <>
          {/* Backdrop */}
          <div
            className="fixed inset-0 z-10"
            onClick={() => setIsOpen(false)}
          />

          {/* Dropdown */}
          <div className="absolute right-0 mt-2 w-64 bg-white rounded-xl shadow-lg border border-gray-200 py-2 z-20 max-h-80 overflow-y-auto">
            <div className="px-4 py-2 text-xs font-semibold text-gray-500 uppercase tracking-wide border-b border-gray-100">
              Choose Language
            </div>

            {Object.entries(supportedLanguages).map(([code, config]) => (
              <button
                key={code}
                onClick={() => changeLanguage(code)}
                className={`w-full px-4 py-3 text-left hover:bg-gray-50 transition-colors duration-150 flex items-center justify-between ${
                  currentLanguage === code ? 'bg-calm-blue-50 text-calm-blue-700' : 'text-gray-700'
                }`}
              >
                <div className="flex flex-col">
                  <span className="font-medium">{config.nativeName}</span>
                  <span className="text-xs text-gray-500">{config.name}</span>
                </div>
                {currentLanguage === code && (
                  <div className="w-2 h-2 bg-calm-blue-600 rounded-full" />
                )}
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

export default LanguageSwitcher;
